from okjson import JSONValidator
from typing import Union

def test_empty():
	schema = {}
	json = "{}"

	assert JSONValidator(
		max_size_in_bytes=1000,
		loosely_typed=False
	).validate(instance=json, schema=schema)

	assert JSONValidator(
		max_size_in_bytes=1000,
		loosely_typed=False
	).is_valid(instance=json, schema=schema)

