	}

	instance = """
	{
		"name": "Charly Gordon",
		"age": 32,
		"marks": {
			"english": 69.4,
			"science": 13.7,
			"mathematics": 10.3,
			"computer_science": 96.4
		},
		"badges": ["computer whiz"]
	}
	"""

	assert JSONValidator(
		max_size_in_bytes=1000,
		loosely_typed=False
	).is_valid(instance=instance, schema=schema)

