def bench_basic_jsonschema():
	schema = {
        "type" : "object",
        "properties" : {
            "name" : {"type" : "string"},
            "age" : {"type" : "number"},
            "marks" : {
                "type" : "object",
                "english" : {"type" : "number"},
                "science" : {"type" : "number"},
                "mathematics" : {"type" : "number"},
                "computer_science" : {"type" : "number"}
            },
            "badges" : {"type": "array"}
        },
	}

	instance = json.loads("""
	{
		"name": "Charly Gordon",
		"age": 32,
		"marks": {
			"english": "s",
			"science": 13.7,
			"mathematics": 10.3,
			"computer_science": 96.4
		},
		"badges": ["computer whiz"]
	}
	""")

	assert validate(instance=instance, schema=schema) == None

def bench_basic_fastjsonschema():
	validate = fastjsonschema.compile({
        "type" : "object",
        "properties" : {
            "name" : {"type" : "string"},
            "age" : {"type" : "number"},
            "marks" : {
                "type" : "object",
                "english" : {"type" : "number"},
                "science" : {"type" : "number"},
                "mathematics" : {"type" : "number"},
                "computer_science" : {"type" : "number"}
            },
            "badges" : {"type": "array"}
        },
	})

	instance = json.loads("""
	{
		"name": "Charly Gordon",
		"age": 32,
		"marks": {
			"english": "s",
			"science": 13.7,
			"mathematics": 10.3,
			"computer_science": 96.4
		},
		"badges": ["computer whiz"]
	}
	""")

	assert validate(instance) != None

def okjson_is_valid_example():
    schema = {
        'name': str,
        'price': float
    }

    assert JSONValidator(
		max_size_in_bytes=1000,
		loosely_typed=False
	).is_valid(instance={"name" : "Eggs", "price" : 34.99}, schema=schema)

