def jsonschema_example():
    schema = {
        "type" : "object",
        "properties" : {
            "price" : {"type" : "number"},
            "name" : {"type" : "string"},
        },
    }

    assert validate(instance={"name" : "Eggs", "price" : 34.99}, schema=schema) == None    

def fastjsonschema_example():
    validate = fastjsonschema.compile({
        "type" : "object",
        "properties" : {
            "price" : {"type" : "number"},
            "name" : {"type" : "string"},
        },
    })

    assert validate({"name" : "Eggs", "price" : 34.99}) != None

